import { Icon } from "@/registry/erbium/ui/icon";

import { Field, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/registry/erbium/ui/input-group";

export function InputGroupInlineEnd() {
  return (
    <Field className="max-w-sm">
      <FieldLabel>Input</FieldLabel>
      <InputGroup>
        <InputGroupInput type="password" placeholder="Enter password" />
        <InputGroupAddon align="inline-end">
          <Icon name="eye-off" />
        </InputGroupAddon>
      </InputGroup>
      <FieldDescription>Icon positioned at the end.</FieldDescription>
    </Field>
  );
}

import { InputGroupInlineEnd } from "../examples/input-group-inline-end";

const Example = () => <InputGroupInlineEnd />;

export default Example;
